@dataclass(frozen=True, slots=True, eq=False)
class _DeferredResultCarrier:
    """Retained result alternatives differ from contained element edges."""

    role: Literal["alternative", "element"]
    roots: tuple[_FlowValue, ...]


@dataclass(frozen=True, slots=True)
class _NativeCollectionEffect:
    owner_refs: tuple[int, ...]
    mutable_identity: int | None
    shape_exact: bool


def _ordered_flow_roots(
    groups: Iterable[Iterable[_FlowValue]], budget: _AnalysisBudget,
) -> tuple[_FlowValue, ...]:
    budget.consume(3)
    result: list[_FlowValue] = []
    seen: set[tuple[int, tuple[int, ...]]] = set()
    for group in groups:
        budget.consume()
        for value in group:
            budget.consume(2 + len(value.authority_refs))
            key = (id(value), value.authority_refs)
            if key not in seen:
                seen.add(key)
                result.append(value)
    budget.consume(1 + len(result))
    return tuple(result)


def _join_member_obligations(
    left: tuple[tuple[str, tuple[_FlowValue, ...]], ...],
    right: tuple[tuple[str, tuple[_FlowValue, ...]], ...],
    budget: _AnalysisBudget,
) -> tuple[tuple[str, tuple[_FlowValue, ...]], ...]:
    if left is right:
        budget.consume()
        return left
    budget.consume(2)
    grouped: dict[str, list[tuple[_FlowValue, ...]]] = {}
    for supplied in (left, right):
        for name, roots in supplied:
            budget.consume(2)
            grouped.setdefault(name, []).append(roots)
    result = []
    for name, groups in grouped.items():
        budget.consume(2)
        roots = _ordered_flow_roots(groups, budget)
        if roots:
            result.append((name, roots))
    budget.consume(1 + len(result))
    return tuple(result)

