def _class_generator_requires_refusal(self, state: _DeferredGeneratorState) -> bool:
    self.budget.consume()
    return bool(state.class_scope_unresolved and (
        state.remaining != 0 or self._deferred_generator_outer_iterator_changed(state)
    ))

def _deferred_result_values(
    self, value: _FlowValue, values: Mapping[str, _FlowValue], *, immediate: bool,
) -> tuple[_FlowValue, ...]:
    """Walk retained edges; element visits cannot suppress alternative visits."""
    self.budget.consume(5)
    pending = [("alternative", value)]
    seen_values: set[tuple[str, int]] = set()
    seen_authority: set[tuple[str, int]] = set()
    result: list[_FlowValue] = []
    store = self._authority(values)
    while pending:
        role, current = pending.pop()
        self.budget.consume(2)
        if immediate and role == "element":
            continue
        key = (role, id(current))
        if key in seen_values:
            continue
        seen_values.add(key)
        if current.kind == "deferred_result_carrier" and isinstance(
            current.value, _DeferredResultCarrier,
        ):
            self.budget.consume(len(current.value.roots))
            pending.extend((current.value.role, root) for root in current.value.roots)
            continue
        if current.kind == "generator" and isinstance(current.value, _DeferredGeneratorState):
            if immediate or current.value.class_scope_unresolved:
                result.append(current)
            continue
        if current.kind == "deferred_local_generator":
            if immediate:
                result.append(current)
            continue
        if current.kind == "deferred_generator_merged":
            for item in current.value:
                self.budget.consume(2)
                if isinstance(item, _DeferredGeneratorState):
                    pending.append(("alternative", _FlowValue("generator", item)))
                elif isinstance(item, _FlowValue):
                    pending.append(("alternative", item))
            continue
        if current.kind in {"maybe_unbound", "deferred_generator_container_merged"}:
            self.budget.consume(len(current.value))
            pending.extend(("alternative", item) for item in current.value
                           if isinstance(item, _FlowValue))
        native = current.kind in {"sequence", "mapping", "mapping_keys", "slice"}
        if native and not immediate:
            if current.kind in {"sequence", "slice"}:
                children = current.value
            else:
                children = tuple(item for pair in current.value for item in pair
                                 if isinstance(item, _FlowValue))
            self.budget.consume(len(children))
            pending.extend(("element", item) for item in children
                           if isinstance(item, _FlowValue))
        if current.kind == "starred_argument" and isinstance(current.value, _FlowValue):
            pending.append((role, current.value))
        for identity in current.authority_refs:
            self.budget.consume()
            authority_key = (role, identity)
            if authority_key in seen_authority:
                continue
            seen_authority.add(authority_key)
            record = store.objects.get(identity)
            if record is not None:
                pending.append((role, record.value))
                retained_role = ("element" if record.value.mutable_collection else role)
                self.budget.consume(len(record.retained))
                pending.extend((retained_role, item) for item in record.retained)
        # A callable's captures/defaults are not its result or immediate iterator.
        if current.callable_definition is None and current.kind in {
            "unknown", "maybe_unbound", "deferred_generator_container_merged",
        }:
            self.budget.consume(len(current.helper_obligations))
            pending.extend((role, item) for item in current.helper_obligations)
    return _ordered_flow_roots((result,), self.budget)

def _retained_deferred_values(
    self, value: _FlowValue, values: Mapping[str, _FlowValue],
) -> tuple[_FlowValue, ...]:
    return self._deferred_result_values(value, values, immediate=False)

def _immediate_deferred_values(
    self, value: _FlowValue, values: Mapping[str, _FlowValue],
) -> tuple[_FlowValue, ...]:
    return self._deferred_result_values(value, values, immediate=True)

def _carrier_result(
    self, result: _FlowValue, role: Literal["alternative", "element"],
    roots: Iterable[_FlowValue],
) -> _FlowValue:
    supplied = _ordered_flow_roots((roots,), self.budget)
    if not supplied:
        return result
    self.budget.consume(3 + len(result.helper_obligations))
    carrier = _FlowValue("deferred_result_carrier", _DeferredResultCarrier(role, supplied))
    return replace(result, authority_refs=(), helper_obligations=(
        *result.helper_obligations, carrier,
    ))

def _element_result_values(
    self, value: _FlowValue, values: Mapping[str, _FlowValue],
) -> tuple[_FlowValue, ...]:
    """Return may-elements, retaining wrappers until actual extraction."""
    self.budget.consume(4)
    pending = [value]
    seen_values: set[int] = set()
    seen_authority: set[int] = set()
    result: list[_FlowValue] = []
    store = self._authority(values)
    while pending:
        current = pending.pop()
        self.budget.consume(2)
        if id(current) in seen_values:
            continue
        seen_values.add(id(current))
        if current.kind == "deferred_result_carrier" and isinstance(
            current.value, _DeferredResultCarrier,
        ):
            self.budget.consume(len(current.value.roots))
            if current.value.role == "element":
                result.extend(current.value.roots)
            else:
                pending.extend(current.value.roots)
        elif current.kind in {"sequence", "slice"}:
            self.budget.consume(len(current.value))
            result.extend(item for item in current.value if isinstance(item, _FlowValue))
        elif current.kind in {"mapping", "mapping_keys"}:
            self.budget.consume(2 * len(current.value))
            result.extend(item for pair in current.value for item in pair
                          if isinstance(item, _FlowValue))
        elif current.kind in {"maybe_unbound", "deferred_generator_container_merged"}:
            self.budget.consume(len(current.value))
            pending.extend(item for item in current.value if isinstance(item, _FlowValue))
        for identity in current.authority_refs:
            self.budget.consume()
            if identity in seen_authority:
                continue
            seen_authority.add(identity)
            record = store.objects.get(identity)
            if record is not None:
                pending.append(record.value)
                self.budget.consume(len(record.retained))
                for retained in record.retained:
                    if retained.kind == "deferred_result_carrier":
                        pending.append(retained)
                    elif record.value.mutable_collection:
                        result.append(retained)
        if current.callable_definition is None:
            self.budget.consume(len(current.helper_obligations))
            pending.extend(current.helper_obligations)
    return _ordered_flow_roots((result,), self.budget)

def _has_class_member_obligations(
    self, value: _FlowValue, values: Mapping[str, _FlowValue],
) -> bool:
    store = self._authority(values)
    for identity in value.authority_refs:
        self.budget.consume()
        record = store.objects.get(identity)
        if record is not None and (record.member_obligations or record.member_wildcard):
            return True
    return False

def _class_member_obligations(
    self, owner: _FlowValue, member_name: str | None,
    values: Mapping[str, _FlowValue],
) -> tuple[_FlowValue, ...]:
    self.budget.consume(4)
    pending = [owner]
    seen_values: set[int] = set()
    seen_authority: set[int] = set()
    roots: list[_FlowValue] = []
    store = self._authority(values)
    while pending:
        current = pending.pop()
        self.budget.consume(2)
        if id(current) in seen_values:
            continue
        seen_values.add(id(current))
        for identity in current.authority_refs:
            self.budget.consume()
            if identity in seen_authority:
                continue
            seen_authority.add(identity)
            record = store.objects.get(identity)
            if record is None:
                roots.append(_FlowValue("helper_deferred_refusal",
                                        reason="helper namespace authority state is unresolved"))
                continue
            for name, supplied in record.member_obligations:
                self.budget.consume(1 + len(supplied))
                if member_name is None or name == member_name:
                    roots.extend(supplied)
            self.budget.consume(len(record.member_wildcard) + len(record.retained))
            roots.extend(record.member_wildcard)
            pending.extend(record.retained)
            pending.append(record.value)
        if current.kind == "deferred_result_carrier" and isinstance(
            current.value, _DeferredResultCarrier,
        ) and current.value.role == "alternative":
            self.budget.consume(len(current.value.roots))
            pending.extend(current.value.roots)
        if current.kind in {"unknown", "implicit_class_instance", "maybe_unbound"}:
            self.budget.consume(len(current.helper_obligations))
            pending.extend(current.helper_obligations)
            if current.kind == "maybe_unbound":
                self.budget.consume(len(current.value))
                pending.extend(item for item in current.value if isinstance(item, _FlowValue))
    return _ordered_flow_roots((roots,), self.budget)

def _with_class_member_authority(
    self, installed: _FlowValue, class_values: Mapping[str, _FlowValue],
    frame: _ClassFrame, bases: Sequence[tuple[ast.expr, _FlowValue]],
    values: Mapping[str, _FlowValue],
) -> _FlowValue:
    if not isinstance(values, _ExecutionState) or not values.authority.enabled:
        return installed
    members: tuple[tuple[str, tuple[_FlowValue, ...]], ...] = ()
    store = self._authority(values)
    for _expression, base in bases:
        for identity in base.authority_refs:
            self.budget.consume()
            record = store.objects.get(identity)
            if record is not None:
                members = _join_member_obligations(
                    members, record.member_obligations, self.budget,
                )
    # Name order comes from the already executed class namespace.
    local_names = frame.scope.local_names - frame.scope.global_names - frame.scope.nonlocal_names
    own = []
    for name, supplied in class_values.items():
        self.budget.consume()
        if name not in local_names or supplied.kind == "unbound":
            continue
        if (self._has_callable_authority(supplied, class_values)
                or self._retained_deferred_values(supplied, class_values)
                or self._has_class_member_obligations(supplied, class_values)):
            own.append((name, (supplied,)))
    members = _join_member_obligations(members, tuple(own), self.budget)
    return _transfer_authority(installed, values, member_obligations=members)

def _retain_class_member_write(
    self, owner: _FlowValue, member_name: str | None,
    supplied: _FlowValue | None, values: Mapping[str, _FlowValue],
) -> None:
    store = self._authority(values)
    roots = (() if supplied is None else (self._transfer(supplied, values),))
    for identity in owner.authority_refs:
        self.budget.consume()
        record = store.objects.get(identity)
        if record is None or not (record.member_obligations or record.member_wildcard):
            continue
        if member_name is None:
            wildcard = _ordered_flow_roots((record.member_wildcard, roots), self.budget)
            store.objects[identity] = replace(record, member_wildcard=wildcard)
        elif roots:
            members = _join_member_obligations(
                record.member_obligations, ((member_name, roots),), self.budget,
            )
            store.objects[identity] = replace(record, member_obligations=members)

def _current_exact_collection_value(
    self, owner: _FlowValue, values: Mapping[str, _FlowValue],
) -> _FlowValue | None:
    store = self._authority(values)
    if not owner.authority_refs:
        return None
    records = []
    for identity in owner.authority_refs:
        self.budget.consume()
        record = store.objects.get(identity)
        if record is None or record.value.kind not in {"sequence", "mapping"}:
            return None
        records.append(record.value)
    self.budget.consume(1 + len(records))
    current = _merge_flow_values("current collection", tuple(records), budget=self.budget)
    if current.kind not in {"sequence", "mapping"}:
        return None
    return replace(current, authority_refs=owner.authority_refs)

def _invalidate_collection_result_shape(
    self, owner: _FlowValue, values: Mapping[str, _FlowValue],
) -> None:
    store = self._authority(values)
    for identity in owner.authority_refs:
        self.budget.consume()
        record = store.objects.get(identity)
        if record is None:
            continue
        current = replace(record.value, authority_refs=(identity,))
        children = self._element_result_values(current, values)
        carrier = self._carrier_result(
            _flow_unknown("collection result shape is unresolved"), "element", children,
        )
        roots = _ordered_flow_roots(
            (record.retained, carrier.helper_obligations), self.budget,
        )
        self.budget.consume()
        store.objects[identity] = replace(
            record, value=replace(record.value, kind="unknown", value=None),
            retained=roots,
        )

